+test("ajustarInventario: recuento mayor agrega un ingreso por la diferencia", () => {
+  const antes = conIngreso();
+  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 14, motivo: "recuento" });
+  assert.equal(antes.length, 1);
+  assert.equal(despues.length, 2);
+  assert.deepEqual(despues[1], { tipo: "ingreso", articulo: "A1", almacen: "LPZ", cantidad: 4, motivo: "recuento" });
+  assert.equal(stock(despues, "A1", "LPZ"), 14);
+});
